"""Port-assignment checks for the extracted EtherCAT tree fixtures.

Fill the blank ``expected_ams_port`` values in each fixture manifest from the
TwinCAT IDE. Passive devices are listed with ``stateful=false`` and no port.
"""

from __future__ import annotations

import csv
from pathlib import Path

import pytest

from pytmc import ethercat, parser

FIXTURE_ROOT = Path(__file__).parent / "projects" / "ethercat_port_assignment"
IO_FIXTURES = {
    "auto_addresses_nested_couplers": (
        FIXTURE_ROOT / "auto_addresses_nested_couplers" / "_Config" / "IO"
    ),
    "fixed_addresses_mixed_order": (
        FIXTURE_ROOT / "fixed_addresses_mixed_order" / "_Config" / "IO"
    ),
}


def _port_is_unfilled(value: str) -> bool:
    return value.strip().lower() in ("", "none")


@pytest.fixture(params=tuple(IO_FIXTURES), ids=tuple(IO_FIXTURES))
def io_fixture(request):
    difficulty = request.param
    io_dir = IO_FIXTURES[difficulty]
    (device_file,) = io_dir.glob("Device*.xti")
    project = parser.parse(device_file)
    project._finish_lazy_loading(parser.Io._pre_load_xti_files(io_dir))
    manifest = FIXTURE_ROOT / difficulty / "expected_ams_ports.csv"
    with manifest.open(newline="", encoding="utf-8") as csv_file:
        rows = list(csv.DictReader(csv_file))
    return difficulty, project, rows, manifest


def test_io_fixture_terminal_inventory(io_fixture):
    _difficulty, project, rows, _manifest = io_fixture
    expected_boxes = [
        (row["box_id"], row["name"])
        for row in rows
    ]
    actual_boxes = [
        (box.attributes.get("Id", ""), box.name)
        for box in project.root.find(parser.Box)
        if getattr(box, "EtherCAT", ())
    ]
    terminals = ethercat.get_ethercat_terminals(project)
    expected_stateful = {
        row["name"] for row in rows if row["stateful"] == "true"
    }
    expected_passive = {
        row["name"] for row in rows if row["stateful"] == "false"
    }

    assert sorted(actual_boxes) == sorted(expected_boxes)
    assert {terminal.name for terminal in terminals} == expected_stateful
    assert {terminal.name for terminal in terminals}.isdisjoint(expected_passive)
    assert all(
        _port_is_unfilled(row["expected_ams_port"])
        for row in rows
        if row["stateful"] == "false"
    )


def test_io_fixture_ports_match_ide_assignments(io_fixture):
    difficulty, project, rows, manifest = io_fixture
    expected = {
        row["name"]: int(row["expected_ams_port"])
        for row in rows
        if row["stateful"] == "true"
        and not _port_is_unfilled(row["expected_ams_port"])
    }
    actual = {
        terminal.name: terminal.port
        for terminal in ethercat.get_ethercat_terminals(project)
    }
    assert {name: actual[name] for name in expected} == expected

    missing = [
        row["name"]
        for row in rows
        if row["stateful"] == "true"
        and _port_is_unfilled(row["expected_ams_port"])
    ]
    if missing:
        pytest.skip(
            f"Fill expected_ams_port in {manifest} for "
            f"{len(missing)} {difficulty} stateful terminals"
        )

    assert actual == expected
